import os,re
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
for r in G['Demo pair 1 output']:
    print(''.join('#' if v else '.' for v in r))

import json
def transform(g):
    g=[row[:] for row in g]; H,W=len(g),len(g[0])
    vc=[c for c in range(W) if all(g[r][c]==3 for r in range(H))][0]
    hr=[r for r in range(H) if all(g[r][c]==3 for c in range(W))][0]
    def put(r,c):
        if 0<=r<H and 0<=c<W and g[r][c]==0: g[r][c]=4
    for h in range(2,max(H,W)+2,2):
        for c in range(vc-h,vc+h+1): put(hr-h,c); put(hr+h,c)
        for r in range(hr-h,hr+h+1): put(r,vc-h); put(r,vc+h)
    return g
demo_in=G['Demo pair 1 input']; demo_out=G['Demo pair 1 output']
print(transform(demo_in)==demo_out)

import json
